import type {
  ColorSpace,
  ColorValueMap,
  HslValue,
  LabValue,
  LchValue,
  OklabValue,
  OklchValue,
  RgbValue,
} from './types';

// Every conversion routes through linear sRGB (0-1, may briefly exceed [0,1]
// for out-of-gamut colors coming from Lab/OKLab before final clamping) so
// each color space only needs a "to/from linear RGB" pair instead of a
// direct function to every other space.
interface LinearRgb {
  r: number;
  g: number;
  b: number;
}

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));

// --- gamma companding (sRGB <-> linear sRGB) ---

function srgbChannelToLinear(c: number): number {
  return c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
}

function linearChannelToSrgb(c: number): number {
  const clamped = Math.max(0, c);
  return clamped <= 0.0031308 ? clamped * 12.92 : 1.055 * Math.pow(clamped, 1 / 2.4) - 0.055;
}

// --- RGB (0-255) <-> linear RGB ---

function rgbToLinear(rgb: RgbValue): LinearRgb {
  return {
    r: srgbChannelToLinear(rgb.r / 255),
    g: srgbChannelToLinear(rgb.g / 255),
    b: srgbChannelToLinear(rgb.b / 255),
  };
}

function linearToRgb(linear: LinearRgb): RgbValue {
  return {
    r: Math.round(clamp(linearChannelToSrgb(linear.r), 0, 1) * 255),
    g: Math.round(clamp(linearChannelToSrgb(linear.g), 0, 1) * 255),
    b: Math.round(clamp(linearChannelToSrgb(linear.b), 0, 1) * 255),
  };
}

// --- HEX <-> RGB ---

export function parseHex(input: string): RgbValue | null {
  const hex = input.trim().replace(/^#/, '');
  if (!/^[0-9a-fA-F]{3}$/.test(hex) && !/^[0-9a-fA-F]{6}$/.test(hex)) return null;

  const full = hex.length === 3
    ? hex.split('').map((c) => c + c).join('')
    : hex;

  return {
    r: parseInt(full.slice(0, 2), 16),
    g: parseInt(full.slice(2, 4), 16),
    b: parseInt(full.slice(4, 6), 16),
  };
}

export function formatHex(rgb: RgbValue): string {
  const toHex = (c: number) => clamp(Math.round(c), 0, 255).toString(16).padStart(2, '0');
  return `#${toHex(rgb.r)}${toHex(rgb.g)}${toHex(rgb.b)}`;
}

// --- HSL <-> RGB ---

export function rgbToHsl(rgb: RgbValue): HslValue {
  const r = rgb.r / 255;
  const g = rgb.g / 255;
  const b = rgb.b / 255;
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const l = (max + min) / 2;

  if (max === min) return { h: 0, s: 0, l: l * 100 };

  const d = max - min;
  const s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
  let h: number;
  switch (max) {
    case r: h = ((g - b) / d + (g < b ? 6 : 0)); break;
    case g: h = (b - r) / d + 2; break;
    default: h = (r - g) / d + 4; break;
  }
  h *= 60;

  return { h, s: s * 100, l: l * 100 };
}

export function hslToRgb(hsl: HslValue): RgbValue {
  const h = ((hsl.h % 360) + 360) % 360 / 360;
  const s = clamp(hsl.s, 0, 100) / 100;
  const l = clamp(hsl.l, 0, 100) / 100;

  if (s === 0) {
    const v = Math.round(l * 255);
    return { r: v, g: v, b: v };
  }

  const hue2rgb = (p: number, q: number, t: number) => {
    let tt = t;
    if (tt < 0) tt += 1;
    if (tt > 1) tt -= 1;
    if (tt < 1 / 6) return p + (q - p) * 6 * tt;
    if (tt < 1 / 2) return q;
    if (tt < 2 / 3) return p + (q - p) * (2 / 3 - tt) * 6;
    return p;
  };

  const q = l < 0.5 ? l * (1 + s) : l + s - l * s;
  const p = 2 * l - q;

  return {
    r: Math.round(hue2rgb(p, q, h + 1 / 3) * 255),
    g: Math.round(hue2rgb(p, q, h) * 255),
    b: Math.round(hue2rgb(p, q, h - 1 / 3) * 255),
  };
}

// --- linear RGB <-> XYZ (D65) <-> CIE Lab ---

const D65 = { x: 0.95047, y: 1.0, z: 1.08883 };

function linearRgbToXyz(linear: LinearRgb) {
  return {
    x: 0.4124564 * linear.r + 0.3575761 * linear.g + 0.1804375 * linear.b,
    y: 0.2126729 * linear.r + 0.7151522 * linear.g + 0.0721750 * linear.b,
    z: 0.0193339 * linear.r + 0.1191920 * linear.g + 0.9503041 * linear.b,
  };
}

function xyzToLinearRgb(xyz: { x: number; y: number; z: number }): LinearRgb {
  return {
    r: 3.2404542 * xyz.x - 1.5371385 * xyz.y - 0.4985314 * xyz.z,
    g: -0.9692660 * xyz.x + 1.8760108 * xyz.y + 0.0415560 * xyz.z,
    b: 0.0556434 * xyz.x - 0.2040259 * xyz.y + 1.0572252 * xyz.z,
  };
}

const LAB_EPSILON = Math.pow(6 / 29, 3);
const LAB_KAPPA = Math.pow(29 / 3, 3);

function labF(t: number): number {
  return t > LAB_EPSILON ? Math.cbrt(t) : (LAB_KAPPA * t + 16) / 116;
}

function labFInv(t: number): number {
  return t > 6 / 29 ? t ** 3 : 3 * (6 / 29) ** 2 * (t - 4 / 29);
}

function xyzToLab(xyz: { x: number; y: number; z: number }): LabValue {
  const fx = labF(xyz.x / D65.x);
  const fy = labF(xyz.y / D65.y);
  const fz = labF(xyz.z / D65.z);
  return {
    l: 116 * fy - 16,
    a: 500 * (fx - fy),
    b: 200 * (fy - fz),
  };
}

function labToXyz(lab: LabValue) {
  const fy = (lab.l + 16) / 116;
  const fx = fy + lab.a / 500;
  const fz = fy - lab.b / 200;
  return {
    x: D65.x * labFInv(fx),
    y: D65.y * labFInv(fy),
    z: D65.z * labFInv(fz),
  };
}

// --- LCH <-> Lab (polar form of Lab, and of OKLab for OKLCH) ---

function labToLch(lab: { l: number; a: number; b: number }) {
  const c = Math.sqrt(lab.a ** 2 + lab.b ** 2);
  let h = Math.atan2(lab.b, lab.a) * (180 / Math.PI);
  if (h < 0) h += 360;
  return { l: lab.l, c, h };
}

function lchToLab(lch: { l: number; c: number; h: number }) {
  const hRad = (lch.h * Math.PI) / 180;
  return {
    l: lch.l,
    a: lch.c * Math.cos(hRad),
    b: lch.c * Math.sin(hRad),
  };
}

// --- linear RGB <-> OKLab (Björn Ottosson's formulas) ---

function linearRgbToOklab(linear: LinearRgb): OklabValue {
  const l = 0.4122214708 * linear.r + 0.5363325363 * linear.g + 0.0514459929 * linear.b;
  const m = 0.2119034982 * linear.r + 0.6806995451 * linear.g + 0.1073969566 * linear.b;
  const s = 0.0883024619 * linear.r + 0.2817188376 * linear.g + 0.6299787005 * linear.b;

  const l_ = Math.cbrt(l);
  const m_ = Math.cbrt(m);
  const s_ = Math.cbrt(s);

  return {
    l: 0.2104542553 * l_ + 0.7936177850 * m_ - 0.0040720468 * s_,
    a: 1.9779984951 * l_ - 2.4285922050 * m_ + 0.4505937099 * s_,
    b: 0.0259040371 * l_ + 0.7827717662 * m_ - 0.8086757660 * s_,
  };
}

function oklabToLinearRgb(oklab: OklabValue): LinearRgb {
  const l_ = oklab.l + 0.3963377774 * oklab.a + 0.2158037573 * oklab.b;
  const m_ = oklab.l - 0.1055613458 * oklab.a - 0.0638541728 * oklab.b;
  const s_ = oklab.l - 0.0894841775 * oklab.a - 1.2914855480 * oklab.b;

  const l = l_ ** 3;
  const m = m_ ** 3;
  const s = s_ ** 3;

  return {
    r: 4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
    g: -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
    b: -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s,
  };
}

// --- top-level: any space -> linear RGB (the hub) ---

function toLinearRgb(space: ColorSpace, value: ColorValueMap[ColorSpace]): LinearRgb | null {
  switch (space) {
    case 'hex': {
      const rgb = parseHex(value as string);
      return rgb ? rgbToLinear(rgb) : null;
    }
    case 'rgb':
      return rgbToLinear(value as RgbValue);
    case 'hsl':
      return rgbToLinear(hslToRgb(value as HslValue));
    case 'lab':
      return xyzToLinearRgb(labToXyz(value as LabValue));
    case 'lch':
      return xyzToLinearRgb(labToXyz(lchToLab(value as LchValue)));
    case 'oklab':
      return oklabToLinearRgb(value as OklabValue);
    case 'oklch': {
      const oklch = value as OklchValue;
      return oklabToLinearRgb(lchToLab(oklch) as OklabValue);
    }
    default:
      return null;
  }
}

// --- top-level: linear RGB -> every space ---

function fromLinearRgb(linear: LinearRgb): ColorValueMap {
  const rgb = linearToRgb(linear);
  const xyz = linearRgbToXyz(linear);
  const lab = xyzToLab(xyz);
  const lch = labToLch(lab);
  const oklab = linearRgbToOklab(linear);
  const oklchPolar = labToLch(oklab);
  const oklch: OklchValue = { l: oklab.l, c: oklchPolar.c, h: oklchPolar.h };

  return {
    hex: formatHex(rgb),
    rgb,
    hsl: rgbToHsl(rgb),
    lab,
    lch,
    oklab,
    oklch,
  };
}

/**
 * Converts one color space's value into every supported color space.
 * Returns null if the input value can't be parsed/is invalid.
 */
export function convertAll<S extends ColorSpace>(space: S, value: ColorValueMap[S]): ColorValueMap | null {
  const linear = toLinearRgb(space, value);
  if (!linear || Object.values(linear).some((v) => Number.isNaN(v))) return null;
  return fromLinearRgb(linear);
}

// --- display / copy formatting ---
// Plain comma-separated numbers in each space's native range (RGB 0-255,
// Lab/LCH L 0-100, OKLab/OKLCH L 0-1, hue in degrees) — no function name,
// no "%" — so the value can be pasted straight into a design tool's numeric
// fields or code as-is (e.g. "43, 45, 65"). Hex stays a single string since
// it isn't a multi-value tuple.

export function formatColorValue(space: ColorSpace, value: ColorValueMap[ColorSpace]): string {
  switch (space) {
    case 'hex':
      return value as string;
    case 'rgb': {
      const v = value as RgbValue;
      return `${Math.round(v.r)}, ${Math.round(v.g)}, ${Math.round(v.b)}`;
    }
    case 'hsl': {
      const v = value as HslValue;
      return `${round(v.h)}, ${round(v.s)}, ${round(v.l)}`;
    }
    case 'lab': {
      const v = value as LabValue;
      return `${round(v.l)}, ${round(v.a)}, ${round(v.b)}`;
    }
    case 'lch': {
      const v = value as LchValue;
      return `${round(v.l)}, ${round(v.c)}, ${round(v.h)}`;
    }
    case 'oklab': {
      const v = value as OklabValue;
      return `${round(v.l, 3)}, ${round(v.a, 3)}, ${round(v.b, 3)}`;
    }
    case 'oklch': {
      const v = value as OklchValue;
      return `${round(v.l, 3)}, ${round(v.c, 3)}, ${round(v.h)}`;
    }
    default:
      return '';
  }
}

function round(n: number, digits = 1): number {
  const factor = 10 ** digits;
  return Math.round(n * factor) / factor;
}
